// Generates experiments/experiment.1.json .. experiment.21.json — the WORLD-MODEL
// pairwise sweep set. One file per unordered pair of the seven study parameters
// (7 choose 2 = 21; A x B and B x A are the same grid transposed).
//
//   node generate_worldmodel_experiments.js
//
// The BA set lives in experiments-ABGraph/ and is generated by
// generate_experiments.js. The two are NOT comparable — different topology under
// a different calibration — so they are kept in separate directories writing to
// separate results directories.
//
// TIME BASE: 1 tick = 1 month, career = 40 years = 480 ticks. horizon 1440 is
// 3 careers; recordAt is every 12 ticks, i.e. once per simulated year.
"use strict";
const fs = require("fs");
const path = require("path");
const { EXPERT_THRESHOLD } = require("./engine.js");

const OUT_DIR = path.join(__dirname, "experiments");
const TICKS_PER_YEAR = 12;
const CAREER_YEARS = 40;
const HORIZON = 1440;                       // 3 careers
const RECORD_AT = [];                       // yearly: 12, 24, ... 1440
for (let t = TICKS_PER_YEAR; t <= HORIZON; t += TICKS_PER_YEAR) RECORD_AT.push(t);
const REPLICATES = 3;
const SEED = 1;
// 21 was the original resolution, dropped to 15 when a run cost ~3.5s. The CDF
// sampler and the allocation-free mobility path took that to ~0.78s/tick-scaled
// (4.5x), which buys the resolution back: 21x21 at 3 replicates costs less CPU
// than the original 21x21 did at 5. The transitions this model turns on
// (transferRate, aiAtrophyMultiplier) are sharp enough that 15 levels visibly
// alias them — see problems.md P3.
const GRID = 21;

function linspace(lo, hi, n) {
  const out = [];
  for (let i = 0; i < n; i++) out.push(+(lo + (hi - lo) * (i / (n - 1))).toFixed(6));
  return out;
}

// ---------------------------------------------------------------------------
// Study parameters. SEVEN, giving C(7,2) = 21.
//
// Narrowed from eleven after reviewing the 21x21 results. Four were dropped
// because they moved nothing worth a pairing (turnoverRate, learningRateSpread,
// mobilityFriction — see problems.md P1 for the last).
//
// 2026-08: aiRelianceIntensity (rho) was removed from the model, taking the study
// from seven parameters to six and from 21 pairings to 15. It was a constraint over
// aiDampeningBelow and aiAtrophyMultiplier (1 - rho, 5^rho), not a mechanism, and
// its base 5 was an untested exchange rate between the two channels. The pair is now
// PINNED here at what rho = 0.25 derived, so the 15 surviving experiments are
// unchanged. The six that swept rho as an axis are archived under results/ — a lock-
// step path through two parameters is not expressible as a grid, and adding a lock-
// step feature would only re-create rho under another name. For independent sweeps
// of that pair see the BA set (generate_experiments.js), which has always had them.
//
// TWO CORRECTIONS applied for this run, both measured — see problems.md P16/P19.
//
// aiLevelFraction now pins at EXPERT_THRESHOLD (0.585) rather than 0.70. The
// effect saturates above lambda ~0.65, so the old pin sat inside a plateau and
// every lambda-pinned figure reported the maximum-effect regime while
// aiDampeningAbove was switched off by having nobody above the threshold.
//
// entrantExpertiseFloor stops entrants arriving at exactly 0. Together with the
// lambda change this REMOVES the absorbing state that maximum de-skilling used to
// be: the shortfall jumped 70x across the last step of the old reliance sweep, and
// now steps by 1.18-1.36x. Regression-tested in test_world_model.js, stated there
// as the dampening/atrophy pair rather than as a reliance intensity.
//
// STILL OPEN: shareExpert_shortfall saturates — under strong dampening it hits
// exactly 0 and stops discriminating. meanE_shortfall stays informative across the
// whole range (0.0512 -> 0.5814) and is the metric to read.
//
// Ranges are re-centred on the MONTHLY-TICK calibration, not copied from the BA
// set. That matters: under this time base the usable transferRate band is roughly
// 0.11-0.15, so the BA set's [0, 1] sweep would spend ~85% of its cells either
// collapsed (shareExpert 0) or pinned (shareExpert ~0.99), measuring nothing.
// See calibrate_time_base.js and problems.md P3.
// ---------------------------------------------------------------------------
const STUDY_PARAMS = {
  // Centred on the calibrated 0.15. Below ~0.11 the population cannot renew
  // itself; above ~0.22 it pins near the ceiling.
  transferRate: { values: linspace(0.08, 0.26, GRID), default: 0.15 },

  // Centred on the calibrated 0.020. The edges are sharp — at transferRate 0.15,
  // decayRate 0.020 -> 0.024 moves equilibrium meanE 0.66 -> 0.62, and because
  // sd(E) is only ~0.06 that is enough to swing shareExpert substantially.
  decayRate: { values: linspace(0.005, 0.040, GRID), default: 0.020 },

  // Raw [0,2]: 0 = max dampening, 1 = neutral, >1 = amplification. Governs the
  // ABOVE-threshold population, and whether it governs anybody at all depends
  // entirely on aiLevelFraction (measured: it drives a 0.74 spread in shortfall at
  // lambda=0.01 and 0.003 at lambda=0.70), so it is swept in its own right.
  aiDampeningAbove: { values: linspace(0, 2, GRID), default: 1.0 },

  // The AI's reference level. startTopE is 1.0 for any realistic N (P17), so this
  // is an absolute expertise threshold despite the name. Range floors at 0.01
  // rather than 0 to avoid the degenerate ai_level = 0 case.
  //
  // Default is EXPERT_THRESHOLD (0.585), not the earlier 0.70: "the AI is as
  // good as a human we would call expert" is a stated quantity rather than an
  // arbitrary pick, and it sits BELOW the saturation plateau that begins around
  // 0.65. The old pin sat inside that plateau, where lambda stops mattering and
  // aiDampeningAbove governs almost nobody (measured: 0.0037 spread at 0.70 vs
  // 0.1158 at 0.60). Moving it here makes aiDampeningAbove a live parameter in
  // the 15 files that pin lambda.
  aiLevelFraction: { values: linspace(0.01, 1, GRID), default: EXPERT_THRESHOLD },

  // Checked, not assumed: this does NOT wash out over the 1440-tick horizon
  // despite the t=0 cohort being replaced ~3x. meanE at t=1440 still spans
  // 0.42 -> 0.75 across this range, because the starting level feeds institution
  // averages, which is what later entrants learn from.
  expertiseMean: { values: linspace(0, 0.8, GRID), default: 0.28 },

  // Range starts at 0.05 = entrantExpertiseFloor. Entrants can no longer arrive
  // at exactly 0, which is what fed the absorbing state at high reliance (P19).
  //
  // CAVEAT for the bottom cell only: the draw is skew-normal(mean, 0.05, 0) and
  // the floor bites when the mean is within a spread of it, so at a nominal 0.05
  // about half of all entrants land exactly on the floor and the realised mean is
  // 0.070. Realised tracks nominal from ~0.14 up (0.1407 at 0.14, 0.2751 at
  // 0.275). The mean is the parameter being named, so the bottom cell is
  // mislabelled by ~0.02 — the pile-up is a distribution-shape artifact, not the
  // degeneracy the old [0, 0.5] range had.
  entrantExpertiseMean: { values: linspace(0.05, 0.5, GRID), default: 0.05 },
};

// Everything not under study, pinned identically across all 15 files.
//
// NOTE on the three demoted from study: each was measured on the 21x21 x 55 run
// and moved the primary metrics little relative to the ones kept. They are
// pinned at the values that set was run with, so the two sets remain comparable.
const BASE_FIXED = {
  graphSource: "worldModel",
  institutionSizing: "weighted",
  turnoverRate: 1 / 480,        // 40-year career; see problems.md P5
  learningRateSpread: 0.4,
  mobilityFriction: 0,          // measured: an 8x change moved shortfall 0.005 (P1)
  // 40 years x (52,514 annual intake / 200). M is NOT set — it is derived from
  // the world model (245) and setting it throws.
  N: 10504,
  expertiseSpread: 0.30,
  expertiseSkew: 3,
  entrantExpertiseSpread: 0.05,
  entrantExpertiseSkew: 0,
  entrantExpertiseFloor: 0.05,  // no entrant arrives at exactly 0 — see P19
  ambientGrowthRate: 0.001,
  mobilityMode: "hybrid",
  jumpProbability: 0.10,
  competitionAversion: 0.5,
  prestigeWeight: 0.3,
  baseMoveProb: 0.05,
  aiResponseMode: "floor",
  aiGain: 1.0,
  // The two halves of de-skilling below the AI's level, set directly. These are
  // exactly what the removed aiRelianceIntensity = 0.25 derived (1 - 0.25 and
  // 5^0.25), so the 15 experiments that pinned rho simulate precisely what they
  // did before — checked against the recorded columns in results/experiment.1/.
  aiDampeningBelow: 0.75,
  aiAtrophyMultiplier: 1.4953487812212205,
};

const WORLD_MODEL = {
  worldModelPath: "world-model.json",
  mobilityCostsPath: "mobility-costs.json",
  worldModelOptions: {
    useBlocAffinity: true,
    hubSource: "located_in",
    prestigeFrom: "intake",
    zeroIntakePolicy: "floor1",
    useExplicitEdges: true,
  },
};

const keys = Object.keys(STUDY_PARAMS);

// Experiment NUMBERS are stable identities, not positions in a list: results/
// experiment.N/ holds finished CSVs and report.html indexes them by that number.
// So the pairing enumeration still runs over the ORIGINAL seven-parameter order,
// including the removed aiRelianceIntensity, and simply emits nothing for the six
// pairs that involved it. Surviving experiments therefore keep the numbers their
// results were written under; 2, 7, 12, 13, 14 and 15 are retired and stay absent.
// Renumbering 1..15 instead would silently repoint every archived results
// directory at a different pairing.
const HISTORICAL_KEY_ORDER = [
  "transferRate", "decayRate", "aiRelianceIntensity", "aiDampeningAbove",
  "aiLevelFraction", "expertiseMean", "entrantExpertiseMean",
];
const REMOVED_KEYS = new Set(["aiRelianceIntensity"]);

const pairs = [];
for (let i = 0; i < HISTORICAL_KEY_ORDER.length; i++) {
  for (let j = i + 1; j < HISTORICAL_KEY_ORDER.length; j++) {
    pairs.push([HISTORICAL_KEY_ORDER[i], HISTORICAL_KEY_ORDER[j]]);
  }
}
if (HISTORICAL_KEY_ORDER.filter((k) => !REMOVED_KEYS.has(k)).join() !== keys.join()) {
  throw new Error("STUDY_PARAMS no longer matches HISTORICAL_KEY_ORDER minus the removed keys — " +
    "adding a study parameter means appending it to HISTORICAL_KEY_ORDER too, or numbering will shift");
}

fs.mkdirSync(OUT_DIR, { recursive: true });

const manifest = [];
const retired = [];
pairs.forEach(([a, b], idx) => {
  const n = idx + 1;
  if (REMOVED_KEYS.has(a) || REMOVED_KEYS.has(b)) { retired.push(n); return; }
  const fixed = Object.assign({}, BASE_FIXED);
  keys.forEach((k) => { if (k !== a && k !== b) fixed[k] = STUDY_PARAMS[k].default; });

  const config = {
    mode: "grid",
    replicates: REPLICATES,
    horizon: HORIZON,
    recordAt: RECORD_AT,
    seed: SEED,
    pairWithBaseline: true,
    worldModel: WORLD_MODEL,
    fixed,
    params: {
      [a]: { values: STUDY_PARAMS[a].values },
      [b]: { values: STUDY_PARAMS[b].values },
    },
  };

  const file = `experiments/experiment.${n}.json`;
  fs.writeFileSync(path.join(__dirname, file), JSON.stringify(config, null, 2) + "\n");
  manifest.push({ n, file, x: a, y: b, runs: GRID * GRID * REPLICATES * 2 });
});

fs.writeFileSync(
  path.join(__dirname, "experiments.worldmodel.manifest.json"),
  JSON.stringify({
    graphSource: "worldModel", worldModel: WORLD_MODEL,
    ticksPerYear: TICKS_PER_YEAR, careerYears: CAREER_YEARS,
    studyParams: STUDY_PARAMS, baseFixed: BASE_FIXED,
    replicates: REPLICATES, horizon: HORIZON, recordAt: RECORD_AT,
    experiments: manifest,
    // Numbers 2, 7, 12-15 are absent by design: those pairings studied
    // aiRelianceIntensity, removed from the model in 2026-08. Their finished CSVs
    // stay under results/ as an archive, which is why the surviving experiments
    // keep their original numbers rather than being renumbered 1..15.
    retiredExperiments: retired,
  }, null, 2) + "\n"
);

const totalRuns = manifest.reduce((s, m) => s + m.runs, 0);
const rowsPerExp = manifest[0].runs * RECORD_AT.length;

console.log(`wrote ${manifest.length} world-model experiment files: ${manifest.map((m) => m.n).join(", ")}`);
console.log(`  + experiments.worldmodel.manifest.json`);
console.log(`  retired (studied the removed aiRelianceIntensity): ${retired.join(", ")} — results/ kept as archive`);
console.log(`\ntime base: 1 tick = 1 month | career = ${CAREER_YEARS}y = ${CAREER_YEARS * TICKS_PER_YEAR} ticks`);
console.log(`horizon ${HORIZON} = ${HORIZON / TICKS_PER_YEAR} years = ${(HORIZON / (CAREER_YEARS * TICKS_PER_YEAR)).toFixed(1)} careers`);
console.log(`recordAt: every ${TICKS_PER_YEAR} ticks (yearly), ${RECORD_AT.length} records per run`);
console.log(`replicates: ${REPLICATES}`);
console.log(`\nruns per experiment: ${manifest[0].runs.toLocaleString()}  |  total across ${pairs.length}: ${totalRuns.toLocaleString()}`);

// Measured on this machine: ~1.1s per run at N=10504, M=245, horizon=1440.
// Was 5.3s originally; 4.5x faster after (a) the precomputed affinity-CDF
// sampler replaced per-draw rejection sampling and (b) the mobility path was
// made allocation-free. See problems.md R5 and R6.
const SEC_PER_RUN = 1.1;
const cpuHours = (totalRuns * SEC_PER_RUN) / 3600;
console.log(`\nCOST (measured ~${SEC_PER_RUN}s/run, not estimated):`);
console.log(`  ${(manifest[0].runs * SEC_PER_RUN / 3600).toFixed(1)} CPU-hours per experiment | ${cpuHours.toFixed(0)} CPU-hours for all ${pairs.length}`);
[8, 14, 32].forEach((w) => console.log(`    ~${(cpuHours / w).toFixed(0)}h wall at ${w} workers (perfect scaling; real scaling is worse)`));
console.log(`  output: ~${(rowsPerExp * 260 / 1e6).toFixed(0)}MB per experiment -> ~${(rowsPerExp * 260 * pairs.length / 1e9).toFixed(1)}GB total`);
console.log(`\nrun one first and time it:  ./run_experiments.sh 1`);
